export function total(items: { price: number }[]): number {
  if (items.length === 0) return 0;
  return items.reduce((sum, item) => sum + item.price, 0);
}

import { total } from './price';

test('sums prices', () => {
  expect(total([{ price: 2 }, { price: 3 }])).toBe(5);
});

